#pragma once
#include <cstring>
#include <iostream>
#include <iomanip>
#include <vector>
#include <string>
#include "Common.h"

class RegisterFile {
private:
    static const int REG_NUM = 32;
    Immediate prev[REG_NUM];
    Immediate next[REG_NUM];

public:
    RegisterFile() {
        memset(prev, 0, sizeof(prev));
        memset(next, 0, sizeof(next));
    }

    void tick() {
        memcpy(prev, next, sizeof(prev));
    }

    Immediate read(int id) {
        return (id == 0) ? 0 : prev[id];
    }

    void write(int id, Immediate val) {
        next[id] = val;
    }

    void debug() {
        const std::vector<std::string> rf_name = {
            "zero", "ra", "sp", "gp", "tp", "t0", "t1", "t2",
            "s0", "s1", "a0", "a1", "a2", "a3", "a4", "a5",
            "a6", "a7", "s2", "s3", "s4", "s5", "s6", "s7",
            "s8", "s9", "s10", "s11", "t3", "t4", "t5", "t6"
        };

        std::cout << "Register File:" << std::endl;
        for (int i = 0; i < 4; ++i) {
            for (int j = 0; j < 8; ++j) {
                int idx = i * 8 + j;
                std::cout << "x" << std::setw(2) << idx << "(" << rf_name[idx] << ") : ";
                debug_immediate(next[idx], 11);
            }
            std::cout << std::endl;
        }
    }
};
